// src/core/composite.js
/**
 * Composite: generated by applying operators to primitives or other composites.
 * Mathematical mapping: X = o(X_1, ..., X_n | C)
 * Whole/part duality: X_n = whole(X_{n-1}), X_n = part(X_{n+1})
 */
export class Composite {
  constructor({
    id,
    scale,
    children,
    operatorId,
    context = {},
    derivationId,
  }) {
    if (!id || !scale || !operatorId || !derivationId) {
      throw new TypeError(
        "Composite requires id, scale, operatorId, and derivationId.",
      );
    }

    if (!Array.isArray(children) || children.length === 0) {
      throw new TypeError("Composite requires at least one child.");
    }

    this.id = id;
    this.scale = scale;
    this.children = Object.freeze([...children]);
    this.operatorId = operatorId;
    this.context = Object.freeze({ ...context });
    this.derivationId = derivationId;

    Object.freeze(this);
  }

  toJSON() {
    return {
      id: this.id,
      scale: this.scale,
      children: [...this.children],
      operatorId: this.operatorId,
      context: { ...this.context },
      derivationId: this.derivationId,
    };
  }

  static fromJSON(data) {
    return new Composite(data);
  }
}
